function CountLowerCaseOdd(txt: string): int
    requires txt != null
    ensures result >= 0
{
    var count := 0;
    var i := 0;
    while i < txt.Length
        invariant 0 <= i <= txt.Length
        invariant count >= 0
    {
        if txt[i] >= 'a' && txt[i] <= 'z' && (txt[i] - 'a') % 2 == 1 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
